74	  public static BootstrapIndexType getBootstrapIndexType(HoodieConfig config) {
75	    if (!config.getBooleanOrDefault(BOOTSTRAP_INDEX_ENABLE)) {
76	      return BootstrapIndexType.NONE;
77	    }
78	    return BootstrapIndexType.valueOf(BOOTSTRAP_INDEX_TYPE.defaultValue());
79	  }
